/**
 * Checks if a given value is strictly less than another value.
 * 
 * @param {any} data.src - The value to check.
 * @param {any} data.ref - The reference value to compare against.
 * @param {Function|string} [data.out] - Optional output handler: function to transform result or string with format.
 *
 * Direct-mode specific parameters:
 * @param {Function} [data.pre] - Optional pre-processor function to transform `src` before checking.
 * 
 * @returns {boolean} True if the value is strictly less than the reference, false otherwise or if either value is not a number.
 *
 * @framework ggLowCodeGTMKit
 */
const makeNumber = require('makeNumber');

const isLessThan = function(value, reference) {
	value = makeNumber(value);
	if (typeof value !== 'number') { 
		return false;
	}
	return value < makeNumber(reference);
};
const safeFunction = fn => typeof fn === 'function' ? fn : x => x;
const out = safeFunction(data.out);
// ===============================================================================
// isLessThan - Direct mode
// ===============================================================================
/*
const applyCast = (castFn, value) => safeFunction(castFn)(value);
const value = applyCast(data.pre, data.src);
return out(isLessThan(value, data.ref));
*/
// ===============================================================================
// isLessThan(...) – Apply Mode
// ===============================================================================
return function(value, reference) {
   reference = data.rp1 ? reference : data.ref;
   return out(isLessThan(value, reference));
};


